package com.pettingzoo;

import java.util.Map;
import java.util.TreeMap;

final class AttackAnimationStore
{
    private AttackAnimationStore() {}

    static Map<Integer, Integer> parse(String value)
    {
        Map<Integer, Integer> result = new TreeMap<>();
        if (value == null || value.trim().isEmpty()) return result;
        for (String entry : value.split(";"))
        {
            String[] parts = entry.split("=", 2);
            if (parts.length != 2) continue;
            try
            {
                int npcId = Integer.parseInt(parts[0]);
                int animationId = Integer.parseInt(parts[1]);
                if (npcId >= 0 && animationId >= 0) result.put(npcId, animationId);
            }
            catch (NumberFormatException ignored)
            {
                // Ignore a damaged entry without losing the rest of the learned library.
            }
        }
        return result;
    }

    static String serialize(Map<Integer, Integer> values)
    {
        StringBuilder out = new StringBuilder();
        values.entrySet().stream().sorted(Map.Entry.comparingByKey()).forEach(entry ->
        {
            if (out.length() > 0) out.append(';');
            out.append(entry.getKey()).append('=').append(entry.getValue());
        });
        return out.toString();
    }
}

package com.pettingzoo;

import java.util.Arrays;
