import net.runelite.api.NPC;

final class BossDetector
{
    private static final Set<String> BOSS_NAMES = new HashSet<>(Arrays.asList(
        "abyssal sire", "akkha", "alchemical hydra", "amoxliatl", "araxxor", "artio",
        "avatar of creation", "avatar of destruction", "ba-ba", "barrows",
        "blood moon", "blue moon", "branda the fire queen", "brutus", "bryophyta",
        "callisto", "calvar'ion", "cerberus", "chaos elemental", "chaos fanatic",
        "commander zilyana", "corporeal beast", "corrupted hunllef", "crazy archaeologist",
        "crystalline hunllef", "dagannoth prime", "dagannoth rex", "dagannoth supreme",
        "dawn", "demonic brutus", "deranged archaeologist", "doom of mokhaiotl",
        "duke sucellus", "dusk", "eclipse moon", "eldric the ice king",
        "elidinis' warden", "general graardor", "gemstone crab", "giant mole", "great olm",
        "hespori", "kalphite queen", "kephri", "king black dragon", "kree'arra", "kraken",
        "k'ril tsutsaroth", "mimic", "nex", "nightmare", "nylocas vasilias", "obor", "olm",
        "pestilent bloat",
        "phantom muspah", "phosani's nightmare", "sarachnis", "scorpia", "scurrius",
        "shellbane gryphon", "skotizo", "sol heredit", "sotetseg", "spindel", "tempoross",
        "the corrupted gauntlet", "the gauntlet", "the hueycoatl", "the leviathan",
        "the maiden of sugadinti", "the mimic", "the nightmare", "the whisperer",
        "thermonuclear smoke devil", "tumeken's warden", "tzkal-zuk", "tztok-jad",
        "vardorvis", "venenatis", "verzik vitur", "vet'ion", "vorkath", "wintertodt",
        "whisperer", "xarpus", "yama", "zalcano", "zebak", "zulrah"
    ));

    private BossDetector()
    {
    }

    static boolean isBoss(NPC npc)
    {
        return npc != null && isBossName(npc.getName());
    }

    static boolean isBossName(String rawName)
    {
        String name = CreatureEligibility.cleanName(rawName).toLowerCase(Locale.ENGLISH);
        return BOSS_NAMES.contains(name);
    }
}

package com.pettingzoo;

import java.awt.Color;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.ItemComposition;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.JagexColor;
import net.runelite.api.Model;
import net.runelite.api.ModelData;

final class CaptureBallFactory
{
    private final Client client;
    private ModelData redBall;

    @Inject
    CaptureBallFactory(Client client)
    {
        this.client = client;
    }

    Model create(int height)
    {
        ModelData base = getBase();
        if (base == null)
        {
            return null;
        }
        ModelData frame = base.shallowCopy().cloneVertices();
        frame.translate(0, -Math.max(0, height), 0);
        return frame.light();
    }

    void clear()
    {
        redBall = null;
    }

    private ModelData getBase()
    {
        if (redBall != null)
        {
            return redBall;
        }
        ItemComposition snowball = client.getItemDefinition(ItemID.GUBLINCH_SNOWBALL);
        if (snowball == null)
        {
            return null;
        }
        ModelData source = client.loadModelData(snowball.getInventoryModel());
        if (source == null)
        {
            return null;
        }
        ModelData data = source.shallowCopy().cloneVertices().cloneColors();
        if (data.getFaceTextures() != null)
        {
            data = data.cloneTextures();
        }
        if (data.getFaceTransparencies() != null)
        {
            data = data.cloneTransparencies();
        }

        short red = JagexColor.rgbToHSL(new Color(218, 45, 60).getRGB(), 1.0);
        short[] colors = data.getFaceColors();
        if (colors != null)
        {
            short[] originals = colors.clone();
            for (short original : originals)
            {
                data.recolor(original, red);
            }
        }
        data.scale(82, 82, 82);
        redBall = data;
        return redBall;
    }
}

