package com.pettingzoo;

import java.util.Arrays;
import java.util.HashSet;
import java.util.Locale;
import java.util.Set;
import java.util.regex.Pattern;
import net.runelite.api.NPC;
import net.runelite.api.NPCComposition;

final class CreatureEligibility
{
    private static final Set<Integer> HUMAN_WALKS = new HashSet<>(Arrays.asList(
        754, 756, 819, 820, 821, 822, 826, 839,
        1323, 1324, 1325, 1326, 4226, 4227, 5602,
        7629, 7630, 7631, 7632, 8462, 10414, 11089, 11090, 11593, 12525
    ));
    private static final Set<Integer> HUMAN_IDLES = new HashSet<>(Arrays.asList(808, 809, 813, 8051));
    private static final Set<String> HUMAN_SERVICE_ACTIONS = new HashSet<>(Arrays.asList(
        "trade", "trade with", "pickpocket", "bank", "exchange", "assignment",
        "makeover", "recruit", "hire", "pay", "tan", "shop"
    ));
    private static final Pattern HUMANOID_NAME = Pattern.compile(
        "(^|\\b)(man|woman|guard|knight|soldier|warrior|archer|ranger|mage|wizard|"
            + "banker|shopkeeper|farmer|miner|smith|priest|monk|druid|pirate|bandit|"
            + "thief|rogue|barbarian|villager|citizen|worker|gnome|dwarf|goblin|troll|"
            + "elf|vampire|zombie|skeleton|ghost|giant|cyclops|ogre|tzhaar)(\\b|$)",
        Pattern.CASE_INSENSITIVE);
    private static final Pattern CREATURE_NAME = Pattern.compile(
        "(^|\\b)(dog|cat|kitten|wolf|fox|bear|rat|mouse|cow|calf|bull|sheep|ram|goat|"
            + "chicken|bird|duck|penguin|spider|snake|serpent|dragon|wyrm|wyvern|hound|"
            + "boar|pig|rabbit|hare|crab|lobster|fish|shark|bat|monkey|ape|camel|horse|"
            + "unicorn|scorpion|beetle|ant|frog|toad|lizard|salamander|fly|flies|bee|wasp|"
            + "moth|butterfly|snail|slug|worm|grub|locust|scarab|cockroach|mosquito|swarm|"
            + "lion|tiger|leopard|jaguar|panther|hyena|crocodile|tortoise|turtle|deer|stag|"
            + "elk|yak|ox|buffalo|antelope|gazelle|eagle|hawk|owl|vulture|raven|crow|gull|"
            + "albatross|parrot|seal|walrus|whale|dolphin|octopus|squid|kraken|imp|demon|"
            + "fiend|hellhound|hydra|basilisk|cockatrice|kurask|turoth|gargoyle|bloodveld|"
            + "banshee|nechryael|abyssal|araxyte|dagannoth|chompy)(\\b|$)",
        Pattern.CASE_INSENSITIVE);
    private static final Pattern KNOWN_BEAST = Pattern.compile(
        "(^|\\b)(zulrah|vorkath|olm|scurrius|callisto|venenatis|cerberus|hueycoatl|"
            + "hespori|jad|zuk|kephri|zebak|akkha|amoxliatl|mole)(\\b|$)",
        Pattern.CASE_INSENSITIVE);
    private static final Pattern PROP_OR_EFFECT = Pattern.compile(
        "(^|\\b)(portal|crate|barricade|barrier|glyph|totem|monolith|ore|rock|boulder|"
            + "boat|ship|cart|cannon|catapult|ballista|anvil|furnace|altar|statue|door|"
            + "gate|wall|pillar|column|table|chair|bed|chest|coffin|sarcophagus|plant|"
            + "tree|stump|root|flower|mushroom|pool|puddle|wave|fire|flame|smoke|cloud|"
            + "shadow|light|spark|energy|rift|vortex|orb|projectile|spell|animation|effect|"
            + "icon|marker|target|dummy|display|scenery|debris|rubble|wreckage)(\\b|$)",
        Pattern.CASE_INSENSITIVE);

    private CreatureEligibility() {}

    static boolean isCatchable(NPC npc)
    {
        if (npc == null) return false;
        NPCComposition composition = npc.getTransformedComposition();
        if (composition == null) composition = npc.getComposition();
        return isCatchable(npc.getName(), npc.getIdlePoseAnimation(), npc.getWalkAnimation(), composition);
    }

    static boolean isCatchable(String name, int idle, int walk, NPCComposition composition)
    {
        name = cleanName(name);
        if (name.isEmpty() || OfficialPetProtection.isProtected(name) || isExplicitlyExcluded(name)
            || isHumanAnimation(idle, walk)) return false;
        String[] actions = composition == null ? null : composition.getActions();
        if (hasHumanServiceAction(actions)) return false;
        int[] models = composition == null ? null : composition.getModels();
        boolean assembledHumanShape = composition != null && composition.getSize() == 1
            && models != null && models.length >= 5;
        boolean namedHumanoid = HUMANOID_NAME.matcher(name).find();
        boolean namedCreature = CREATURE_NAME.matcher(name).find() || KNOWN_BEAST.matcher(name).find();
        if (assembledHumanShape && (containsAction(actions, "Talk-to")
            || containsAction(actions, "Attack") || namedHumanoid) && !namedCreature) return false;
        return !namedHumanoid || namedCreature;
    }

    static boolean isCatalogueCreature(String rawName, NPCComposition composition)
    {
        String name = cleanName(rawName);
        if (name.isEmpty() || OfficialPetProtection.isProtected(name) || isExplicitlyExcluded(name)
            || composition == null || PROP_OR_EFFECT.matcher(name).find()) return false;
        boolean namedCreature = CREATURE_NAME.matcher(name).find()
            || KNOWN_BEAST.matcher(name).find() || composition.isFollower();
        if (namedCreature) return true;
        String[] actions = composition.getActions();
        if (containsAction(actions, "Talk-to") || hasHumanServiceAction(actions)
            || HUMANOID_NAME.matcher(name).find()) return false;
        return composition.getCombatLevel() > 0 && containsAction(actions, "Attack");
    }

    static String cleanName(String value)
    {
        return value == null ? "" : value.replaceAll("<[^>]*>", "").trim();
    }

    static boolean isExplicitlyExcluded(String rawName)
    {
        return "Gemstone Crab".equalsIgnoreCase(cleanName(rawName));
    }
    static boolean isHumanAnimation(int idle, int walk)
    {
        return HUMAN_IDLES.contains(idle) || HUMAN_WALKS.contains(walk);
    }

    static boolean hasHumanServiceAction(String[] actions)
    {
        if (actions == null) return false;
        for (String action : actions)
        {
            if (action != null && HUMAN_SERVICE_ACTIONS.contains(action.toLowerCase(Locale.ENGLISH))) return true;
        }
        return false;
    }

    private static boolean containsAction(String[] actions, String expected)
    {
        if (actions == null) return false;
        for (String action : actions)
        {
            if (expected.equalsIgnoreCase(action)) return true;
        }
        return false;
    }
}

package com.pettingzoo;

import java.awt.Color;
import java.awt.GradientPaint;
import java.awt.Graphics2D;
import java.awt.Polygon;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import net.runelite.api.Model;

final class ModelPreviewRenderer
{
    private ModelPreviewRenderer()
    {
    }

    static boolean hasVisibleGeometry(Model model)
    {
        if (model == null || model.getVerticesCount() <= 0 || model.getFaceCount() <= 0)
        {
            return false;
        }
        float[] x = model.getVerticesX();
        float[] y = model.getVerticesY();
        float[] z = model.getVerticesZ();
        int[] a = model.getFaceIndices1();
        int[] b = model.getFaceIndices2();
        int[] c = model.getFaceIndices3();
        int[] colors = model.getFaceColors1();
        byte[] alpha = model.getFaceTransparencies();
        if (x == null || y == null || z == null || a == null || b == null || c == null || colors == null)
        {
            return false;
        }
        int vertices = Math.min(model.getVerticesCount(), Math.min(x.length, Math.min(y.length, z.length)));
        int faces = Math.min(model.getFaceCount(), Math.min(colors.length,
            Math.min(a.length, Math.min(b.length, c.length))));
        for (int face = 0; face < faces; face++)
        {
            int ia = a[face], ib = b[face], ic = c[face];
            if (colors[face] == -2 || alpha != null && face < alpha.length && (alpha[face] & 255) == 255
                || ia < 0 || ib < 0 || ic < 0 || ia >= vertices || ib >= vertices || ic >= vertices)
            {
                continue;
            }
            double abx = x[ib] - x[ia], aby = y[ib] - y[ia], abz = z[ib] - z[ia];
            double acx = x[ic] - x[ia], acy = y[ic] - y[ia], acz = z[ic] - z[ia];
            double cx = aby * acz - abz * acy;
            double cy = abz * acx - abx * acz;
            double cz = abx * acy - aby * acx;
            if (cx * cx + cy * cy + cz * cz > 0.01)
            {
                return true;
            }
        }
        return false;
    }
    static BufferedImage render(Model model, int width, int height, boolean locked)
    {
        if (!hasVisibleGeometry(model))
        {
            return null;
        }
        BufferedImage image = new BufferedImage(width, height, BufferedImage.TYPE_INT_ARGB);
        Graphics2D g = image.createGraphics();
        g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
        g.setPaint(new GradientPaint(0, 0, new Color(61, 43, 47),
            0, height, new Color(27, 23, 30)));
        g.fillRoundRect(0, 0, width, height, 14, 14);
        if (!locked)
        {
            g.setColor(new Color(255, 199, 92, 34));
            g.fillOval(10, 12, width - 20, height - 20);
            g.setColor(new Color(255, 223, 145, 38));
            g.drawOval(12, 14, width - 24, height - 24);
        }

        int count = model.getVerticesCount();
        float[] vx = model.getVerticesX(), vy = model.getVerticesY(), vz = model.getVerticesZ();
        if (count <= 0 || vx == null || vy == null || vz == null)
        {
            g.dispose();
            return null;
        }

        double[] x = new double[count], y = new double[count], depth = new double[count];
        double minX = Double.MAX_VALUE, maxX = -Double.MAX_VALUE;
        double minY = Double.MAX_VALUE, maxY = -Double.MAX_VALUE;
        double yaw = Math.toRadians(28), pitch = Math.toRadians(12);
        for (int i = 0; i < count; i++)
        {
            double px = vx[i], py = -vy[i], pz = vz[i];
            double rx = px * Math.cos(yaw) + pz * Math.sin(yaw);
            double rz = -px * Math.sin(yaw) + pz * Math.cos(yaw);
            double ry = py * Math.cos(pitch) - rz * Math.sin(pitch);
            rz = py * Math.sin(pitch) + rz * Math.cos(pitch);
            x[i] = rx;
            y[i] = ry;
            depth[i] = rz;
            minX = Math.min(minX, rx);
            maxX = Math.max(maxX, rx);
            minY = Math.min(minY, ry);
            maxY = Math.max(maxY, ry);
        }

        double scale = Math.min((width - 16d) / Math.max(1d, maxX - minX),
            (height - 16d) / Math.max(1d, maxY - minY));
        double centerX = (minX + maxX) / 2d;
        double centerY = (minY + maxY) / 2d;
        int[] a = model.getFaceIndices1(), b = model.getFaceIndices2(), c = model.getFaceIndices3();
        int[] colors = model.getFaceColors1();
        byte[] alpha = model.getFaceTransparencies();
        List<Integer> faces = new ArrayList<>();
        for (int i = 0; i < model.getFaceCount(); i++)
        {
            if (a[i] >= 0 && b[i] >= 0 && c[i] >= 0 && a[i] < count && b[i] < count && c[i] < count
                && colors[i] != -2)
            {
                faces.add(i);
            }
        }
        faces.sort(Comparator.comparingDouble(i -> (depth[a[i]] + depth[b[i]] + depth[c[i]]) / 3d));
        double visibleArea = 0;
        for (int face : faces)
        {
            int[] px = new int[]{project(x[a[face]], centerX, scale, width),
                project(x[b[face]], centerX, scale, width),
                project(x[c[face]], centerX, scale, width)};
            int[] py = new int[]{projectY(y[a[face]], centerY, scale, height),
                projectY(y[b[face]], centerY, scale, height),
                projectY(y[c[face]], centerY, scale, height)};
            int opacity = alpha == null || face >= alpha.length ? 255 : 255 - (alpha[face] & 255);
            double area = Math.abs(px[0] * (double) (py[1] - py[2])
                + px[1] * (double) (py[2] - py[0])
                + px[2] * (double) (py[0] - py[1])) / 2d;
            if (opacity < 16 || area < 0.5)
            {
                continue;
            }
            Polygon triangle = new Polygon(px, py, 3);
            Color color = locked ? new Color(23, 19, 26) : hsl(colors[face] < 0 ? 0 : colors[face]);
            g.setColor(new Color(color.getRed(), color.getGreen(), color.getBlue(), opacity));
            g.fillPolygon(triangle);
            visibleArea += area * opacity / 255d;
        }
        if (visibleArea < 8d)
        {
            g.dispose();
            return null;
        }
        if (locked)
        {
            g.setColor(new Color(255, 255, 255, 115));
            g.drawString("?", width - 17, 17);
        }
        g.dispose();
        return image;
    }

    private static int project(double value, double center, double scale, int size)
    {
        return (int) Math.round(size / 2d + (value - center) * scale);
    }

    private static int projectY(double value, double center, double scale, int size)
    {
        return (int) Math.round(size / 2d - (value - center) * scale);
    }

    private static Color hsl(int packed)
    {
        double h = ((packed >> 10) & 63) / 64d;
        double s = ((packed >> 7) & 7) / 8d;
        double l = (packed & 127) / 128d;
        double q = l < .5 ? l * (1 + s) : l + s - l * s;
        double p = 2 * l - q;
        return new Color((float) hue(p, q, h + 1d / 3d),
            (float) hue(p, q, h), (float) hue(p, q, h - 1d / 3d));
    }

    private static double hue(double p, double q, double t)
    {
        if (t < 0) t++;
        if (t > 1) t--;
        if (t < 1d / 6d) return p + (q - p) * 6d * t;
        if (t < .5d) return q;
        if (t < 2d / 3d) return p + (q - p) * (2d / 3d - t) * 6d;
        return p;
    }
}

package com.pettingzoo;

final class NpcDefinitionData
{
    String name;
    int[] modelIds;
    short[] recolorFrom;
    short[] recolorTo;
    short[] retextureFrom;
    short[] retextureTo;
    int standingAnimation = -1;
    int walkingAnimation = -1;
    int runAnimation = -1;
    int crawlAnimation = -1;
    int widthScale = 128;
    int heightScale = 128;
    int ambient;
    int contrast;
    boolean transforms;

    boolean isSafeForCustomRendering()
    {
        if (transforms || modelIds == null || modelIds.length == 0 || modelIds.length > 32)
        {
            return false;
        }
        for (int modelId : modelIds)
        {
            if (modelId < 0)
            {
                return false;
            }
        }
        return true;
    }
}

package com.pettingzoo;

/**
 * Minimal NPC-definition decoder for models and the animations naturally
 * associated with them. Opcode lengths follow RuneLite's cache NpcLoader.
 */
final class NpcDefinitionDecoder
{
    private NpcDefinitionDecoder()
    {
    }

    static NpcDefinitionData decode(byte[] data)
    {
        NpcDefinitionData definition = new NpcDefinitionData();
        if (data == null)
        {
            return definition;
        }
        Reader in = new Reader(data);
        while (in.remaining() > 0)
        {
            int opcode = in.u8();
            if (opcode == 0)
            {
                break;
            }
            decodeOpcode(definition, in, opcode);
        }
        return definition;
    }

    private static void decodeOpcode(NpcDefinitionData d, Reader in, int opcode)
    {
        if (opcode == 1 || opcode == 60)
        {
            int count = in.u8();
            if (opcode == 1)
            {
                d.modelIds = new int[count];
                for (int i = 0; i < count; i++) d.modelIds[i] = in.u16();
            }
            else
            {
                in.skip(count * 2);
            }
        }
        else if (opcode == 2)
        {
            d.name = in.string();
        }
        else if (opcode == 12)
        {
            in.skip(1);
        }
        else if (opcode == 13)
        {
            d.standingAnimation = animation(in.u16());
        }
        else if (opcode == 14)
        {
            d.walkingAnimation = animation(in.u16());
        }
        else if (opcode == 15 || opcode == 16 || opcode == 18 || opcode == 95
            || opcode == 103 || opcode == 124 || opcode == 126 || (opcode >= 74 && opcode <= 79))
        {
            in.skip(2);
        }
        else if (opcode == 17)
        {
            d.walkingAnimation = animation(in.u16());
            in.skip(6);
        }
        else if (opcode >= 30 && opcode < 35)
        {
            in.string();
        }
        else if (opcode == 40 || opcode == 41)
        {
            int count = in.u8();
            short[] from = new short[count];
            short[] to = new short[count];
            for (int i = 0; i < count; i++)
            {
                from[i] = (short) in.u16();
                to[i] = (short) in.u16();
            }
            if (opcode == 40)
            {
                d.recolorFrom = from;
                d.recolorTo = to;
            }
            else
            {
                d.retextureFrom = from;
                d.retextureTo = to;
            }
        }
        else if (opcode == 61 || opcode == 62)
        {
            int count = in.u8();
            if (opcode == 61)
            {
                d.modelIds = new int[count];
                for (int i = 0; i < count; i++) d.modelIds[i] = in.i32();
            }
            else
            {
                in.skip(count * 4);
            }
        }
        else if (opcode == 93 || opcode == 99 || opcode == 107 || opcode == 109
            || opcode == 111 || opcode == 122 || opcode == 123 || opcode == 129
            || opcode == 130 || opcode == 145 || opcode == 147)
        {
            // Flag-only opcodes.
        }
        else if (opcode == 97)
        {
            d.widthScale = in.u16();
        }
        else if (opcode == 98)
        {
            d.heightScale = in.u16();
        }
        else if (opcode == 100)
        {
            d.ambient = in.i8();
        }
        else if (opcode == 101)
        {
            d.contrast = in.i8() * 5;
        }
        else if (opcode == 102)
        {
            int bitfield = in.u8();
            int count = 0;
            for (int bits = bitfield; bits != 0; bits >>>= 1) count++;
            for (int i = 0; i < count; i++)
            {
                if ((bitfield & (1 << i)) != 0)
                {
                    in.bigSmart2();
                    in.unsignedShortSmartMinusOne();
                }
            }
        }
        else if (opcode == 106 || opcode == 118)
        {
            d.transforms = true;
            in.skip(opcode == 118 ? 6 : 4);
            int count = in.u8();
            in.skip((count + 1) * 2);
        }
        else if (opcode == 114)
        {
            d.runAnimation = animation(in.u16());
        }
        else if (opcode == 115)
        {
            d.runAnimation = animation(in.u16());
            in.skip(6);
        }
        else if (opcode == 116)
        {
            d.crawlAnimation = animation(in.u16());
        }
        else if (opcode == 117)
        {
            d.crawlAnimation = animation(in.u16());
            in.skip(6);
        }
        else if (opcode == 146)
        {
            in.skip(2);
        }
        else if (opcode == 249)
        {
            int count = in.u8();
            for (int i = 0; i < count; i++)
            {
                boolean stringValue = in.u8() == 1;
                in.skip(3);
                if (stringValue) in.string(); else in.skip(4);
            }
        }
        else if (opcode == 251)
        {
            in.skip(2);
            in.string();
        }
        else if (opcode == 252)
        {
            in.skip(13);
            in.string();
        }
        else if (opcode == 253)
        {
            in.skip(14);
            in.string();
        }
        else
        {
            throw new IllegalArgumentException("Unknown NPC-definition opcode " + opcode);
        }
    }

    private static int animation(int id)
    {
        return id == 0xFFFF ? -1 : id;
    }

    private static final class Reader
    {
        private final byte[] data;
        private int offset;

        private Reader(byte[] data)
        {
            this.data = data;
        }

        int remaining()
        {
            return data.length - offset;
        }

        int u8()
        {
            require(1);
            return data[offset++] & 0xFF;
        }

        int i8()
        {
            return (byte) u8();
        }

        int u16()
        {
            return (u8() << 8) | u8();
        }

        int i32()
        {
            return (u8() << 24) | (u8() << 16) | (u8() << 8) | u8();
        }

        int bigSmart2()
        {
            require(1);
            return (data[offset] & 0x80) == 0 ? u16() : i32() & 0x7FFFFFFF;
        }

        int unsignedShortSmartMinusOne()
        {
            require(1);
            return (data[offset] & 0xFF) < 128 ? u8() - 1 : u16() - 32769;
        }

        String string()
        {
            StringBuilder value = new StringBuilder();
            int next;
            while ((next = u8()) != 0) value.append((char) next);
            return value.toString();
        }

        void skip(int amount)
        {
            require(amount);
            offset += amount;
        }

        void require(int amount)
        {
            if (amount < 0 || offset + amount > data.length)
            {
                throw new IllegalArgumentException("Truncated NPC definition");
            }
        }
    }
}

