package com.pettingzoo;

import java.nio.charset.StandardCharsets;
import java.util.Base64;
import java.util.Map;
import java.util.TreeMap;

final class PetCollectionStore
{
    private PetCollectionStore()
    {
    }

    static Map<Integer, PetRecord> parse(String value)
    {
        Map<Integer, PetRecord> pets = new TreeMap<>();
        if (value == null || value.trim().isEmpty())
        {
            return pets;
        }

        for (String encoded : value.split(";"))
        {
            String[] fields = encoded.split("\\|");
            if (fields.length != 5 && fields.length != 6)
            {
                continue;
            }
            try
            {
                int npcId = Integer.parseInt(fields[0]);
                int idle = Integer.parseInt(fields[1]);
                int walk = Integer.parseInt(fields[2]);
                int combat = fields.length == 6 ? Integer.parseInt(fields[3]) : -1;
                int caughtIndex = fields.length == 6 ? 4 : 3;
                int nameIndex = fields.length == 6 ? 5 : 4;
                boolean caught = "1".equals(fields[caughtIndex]);
                String name = new String(Base64.getUrlDecoder().decode(fields[nameIndex]), StandardCharsets.UTF_8);
                if (npcId >= 0)
                {
                    pets.put(npcId, new PetRecord(npcId, name, idle, walk, combat, caught));
                }
            }
            catch (IllegalArgumentException ignored)
            {
            }
        }
        return pets;
    }

    static String serialize(Map<Integer, PetRecord> pets)
    {
        StringBuilder result = new StringBuilder();
        for (PetRecord pet : new TreeMap<>(pets).values())
        {
            if (result.length() > 0)
            {
                result.append(';');
            }
            String name = Base64.getUrlEncoder().withoutPadding()
                .encodeToString(pet.name.getBytes(StandardCharsets.UTF_8));
            result.append(pet.npcId).append('|')
                .append(pet.idleAnimation).append('|')
                .append(pet.walkAnimation).append('|')
                .append(pet.combatLevel).append('|')
                .append(pet.caught ? '1' : '0').append('|')
                .append(name);
        }
        return result.toString();
    }
}

package com.pettingzoo;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.Model;
import net.runelite.api.ModelData;
import net.runelite.api.NPCComposition;

final class PetModelFactory
{
    private static final int MAX_VERTICES = 30_000;
    private static final int MAX_FACES = 60_000;

    private final Client client;
    private final Map<Long, Model> cache = new HashMap<>();

    @Inject
    PetModelFactory(Client client)
    {
        this.client = client;
    }

    Model get(int npcId, int scale)
    {
        long key = ((long) npcId << 32) ^ scale;
        Model cached = cache.get(key);
        if (cached != null)
        {
            return cached;
        }
        Model built;
        try
        {
            built = build(npcId, scale);
        }
        catch (RuntimeException | AssertionError ignored)
        {
            return null;
        }
        if (built != null)
        {
            cache.put(key, built);
        }
        return built;
    }

    void clear()
    {
        cache.clear();
    }

    private Model build(int npcId, int scale)
    {
        NPCComposition composition = client.getNpcDefinition(npcId);
        if (composition == null)
        {
            return null;
        }
        if (composition.getConfigs() != null)
        {
            NPCComposition transformed = composition.transform();
            if (transformed != null)
            {
                composition = transformed;
            }
        }

        int[] modelIds = composition.getModels();
        if (modelIds == null || modelIds.length == 0 || modelIds.length > 32)
        {
            return null;
        }
        List<ModelData> parts = new ArrayList<>(modelIds.length);
        for (int modelId : modelIds)
        {
            ModelData source = client.loadModelData(modelId);
            if (source == null)
            {
                return null;
            }
            ModelData part = source.shallowCopy().cloneVertices().cloneColors();
            if (part.getFaceTextures() != null)
            {
                part = part.cloneTextures();
            }
            if (part.getFaceTransparencies() != null)
            {
                part = part.cloneTransparencies();
            }
            parts.add(part);
        }

        ModelData data = parts.size() == 1
            ? parts.get(0) : client.mergeModels(parts.toArray(new ModelData[0]));
        if (data == null)
        {
            return null;
        }

        short[] from = composition.getColorToReplace();
        short[] to = composition.getColorToReplaceWith();
        if (from != null && to != null)
        {
            for (int i = 0; i < Math.min(from.length, to.length); i++)
            {
                data.recolor(from[i], to[i]);
            }
        }

        int width = Math.max(1, composition.getWidthScale() * scale / 100);
        int height = Math.max(1, composition.getHeightScale() * scale / 100);
        data.scale(width, height, width);
        Model model = data.light();
        if (!isSafe(model))
        {
            return null;
        }
        model.calculateBoundsCylinder();
        return model.getDiameter() > 0 && model.getDiameter() < 12_000 ? model : null;
    }

    private static boolean isSafe(Model model)
    {
        return model != null && model.getVerticesCount() > 0 && model.getVerticesCount() <= MAX_VERTICES
            && model.getFaceCount() > 0 && model.getFaceCount() <= MAX_FACES;
    }
}

package com.pettingzoo;

final class PetMovement
{
    private PetMovement()
    {
    }

    static Step advance(int x, int y, int targetX, int targetY,
        int followDistance, int speed, int orientation)
    {
        double dx = targetX - x;
        double dy = targetY - y;
        double distance = Math.hypot(dx, dy);
        if (distance <= followDistance || distance < 1.0)
        {
            return new Step(x, y, orientation, false);
        }

        double travel = Math.min(Math.max(1, speed), distance - followDistance);
        int nextX = (int) Math.round(x + dx / distance * travel);
        int nextY = (int) Math.round(y + dy / distance * travel);
        if (nextX == x && nextY == y)
        {
            return new Step(x, y, orientation, false);
        }
        // NPC models face opposite RuneLite's movement-angle convention.
        int desired = ((int) Math.round(Math.atan2(dx, dy) * 1024.0 / Math.PI) + 1024) & 2047;
        int difference = ((desired - orientation + 1024) & 2047) - 1024;
        difference = Math.max(-96, Math.min(96, difference));
        int nextOrientation = (orientation + difference) & 2047;
        return new Step(nextX, nextY, nextOrientation, true);
    }

    static final class Step
    {
        final int x;
        final int y;
        final int orientation;
        final boolean moving;

        Step(int x, int y, int orientation, boolean moving)
        {
            this.x = x;
            this.y = y;
            this.orientation = orientation;
            this.moving = moving;
        }
    }
}

package com.pettingzoo;

final class PetRecord
{
    final int npcId;
    final String name;
    final int idleAnimation;
    final int walkAnimation;
    final int combatLevel;
    final boolean caught;

    PetRecord(int npcId, String name, int idleAnimation, int walkAnimation, boolean caught)
    {
        this(npcId, name, idleAnimation, walkAnimation, -1, caught);
    }

    PetRecord(int npcId, String name, int idleAnimation, int walkAnimation, int combatLevel, boolean caught)
    {
        this.npcId = npcId;
        this.name = name == null || name.trim().isEmpty() ? "Animal" : name;
        this.idleAnimation = idleAnimation;
        this.walkAnimation = walkAnimation;
        this.combatLevel = combatLevel;
        this.caught = caught;
    }

    PetRecord caught()
    {
        return caught ? this
            : new PetRecord(npcId, name, idleAnimation, walkAnimation, combatLevel, true);
    }
}

