        timer.start();
    }

    void showNewPet(String name)
    {
        showReward("NEW PET! " + name.toUpperCase());
    }

    private void rebuild()
    {
        int currentGeneration = ++generation;
        adjustingControls = true;
        distanceSlider.setValue(plugin.followDistance());
        speedSlider.setValue(plugin.followSpeed());
        sizeSlider.setValue(plugin.petScale());
        customizeCurrentPet.setSelected(plugin.customizeCurrentPet());
        distanceLabel.setText("DISTANCE  " + distanceSlider.getValue() + " tiles");
        speedLabel.setText("SPEED  " + speedSlider.getValue());
        sizeLabel.setText("SIZE  " + sizeSlider.getValue() + "%");
        adjustingControls = false;
        List<PetRecord> collection = plugin.collectionSnapshot();
        long caughtCount = collection.stream().filter(pet -> pet.caught).count();
        balls.setText("CAPTURE BALLS:  " + plugin.ballCount());
        counts.setText(caughtCount + " caught  /  " + collection.size() + " discovered");

        xpProgress.setValue(plugin.xpTowardBall());
        xpProgress.setString((10_000 - plugin.xpTowardBall()) + " XP TO NEXT BALL");
        collectionProgress.setMaximum(Math.max(1, collection.size()));
        collectionProgress.setValue((int) caughtCount);
        collectionProgress.setString(collection.isEmpty() ? "EXPLORE TO BEGIN"
            : Math.round(caughtCount * 100f / collection.size()) + "% OF DISCOVERED PETS CAUGHT");

        String activeName = plugin.activePetName();
        active.setText(activeName == null ? "No cosmetic pet following"
            : "Following: " + activeName);
        dismiss.setVisible(activeName != null);
        dismiss.setText(activeName == null ? "DISMISS CREATURE"
            : "DISMISS " + activeName.toUpperCase());
        boolean canInteract = activeName != null && plugin.canInteractWithActivePet();
        interact.setVisible(canInteract);
        interact.setText(activeName == null ? "INTERACT"
            : "INTERACT WITH " + activeName.toUpperCase());

        String query = search.getText().trim().toLowerCase();
        List<PetRecord> matches = new ArrayList<>();
        for (PetRecord pet : collection)
        {
            if ((!caughtOnly.isSelected() || pet.caught)
                && (query.isEmpty() || pet.name.toLowerCase().contains(query)
                    || Integer.toString(pet.npcId).contains(query)))
            {
                matches.add(pet);
            }
        }

        int pages = Math.max(1, (matches.size() + PAGE_SIZE - 1) / PAGE_SIZE);
        page = Math.min(page, pages - 1);
        previous.setEnabled(page > 0);
        next.setEnabled(page + 1 < pages);
        pageLabel.setText((page + 1) + " / " + pages);
        pets.removeAll();

        int from = page * PAGE_SIZE;
        int to = Math.min(matches.size(), from + PAGE_SIZE);
        for (int i = from; i < to; i++)
        {
            PetRecord pet = matches.get(i);
            JPanel card = createCard(pet, currentGeneration);
            pets.add(card);
        }

        if (matches.isEmpty())
        {
            JLabel empty = centeredLabel();
            empty.setText(collection.isEmpty()
                ? "<html><center>Your book is empty.<br><br>Shift-right-click a creature<br>to discover and catch it!</center></html>"
                : "No creatures match this page");
            empty.setForeground(PARCHMENT);
            pets.add(empty);
        }
        pets.revalidate();
        pets.repaint();
    }

    private JPanel createCard(PetRecord pet, int currentGeneration)
    {
        JPanel card = new JPanel(new BorderLayout(3, 4));
        card.setBackground(pet.caught ? new Color(73, 49, 42) : new Color(48, 40, 45));
        card.setBorder(BorderFactory.createCompoundBorder(
            BorderFactory.createLineBorder(pet.caught ? GOLD : new Color(94, 78, 83),
                pet.caught ? 2 : 1),
            BorderFactory.createEmptyBorder(4, 4, 4, 4)));
        card.setPreferredSize(new Dimension(103, 165));

        JLabel portrait = centeredLabel();
        portrait.setPreferredSize(new Dimension(92, 92));
        portrait.setText("...");
        card.add(portrait, BorderLayout.NORTH);

        String level = pet.combatLevel > 0 ? "Level " + pet.combatLevel : "No level";
        String state = pet.caught ? "CAUGHT" : plugin.catchChance(pet.combatLevel) + "% chance";
        JLabel details = centeredLabel();
        details.setText("<html><center><b>" + escape(pet.name) + "</b><br><small>"
            + level + "<br>" + state + "</small></center></html>");
        details.setForeground(pet.caught ? new Color(255, 224, 145) : new Color(218, 207, 211));
        card.add(details, BorderLayout.CENTER);

        JButton call = new JButton(pet.caught ? "CALL" : "LOCKED");
        call.setEnabled(pet.caught);
        call.setToolTipText(pet.caught ? "Call " + pet.name + " as your follower"
            : "Catch this creature to unlock it");
        call.addActionListener(event -> plugin.activateCaught(pet.npcId));
        card.add(call, BorderLayout.SOUTH);

        plugin.requestPreview(pet, image ->
        {
            if (generation == currentGeneration && image != null)
            {
                portrait.setText("");
                portrait.setIcon(new ImageIcon(image));
            }
            else if (image == null)
            {
                portrait.setText("No portrait");
            }
        });
        return card;
    }

    private static JPanel controlRow(JLabel label, JSlider slider)
    {
        return controlRow(label, slider, null);
    }

    private static JPanel controlRow(JLabel label, JSlider slider, JLabel help)
    {
        JPanel row = new JPanel(new BorderLayout(6, 0));
        row.setOpaque(false);
        label.setForeground(new Color(238, 214, 171));
        label.setFont(label.getFont().deriveFont(Font.BOLD, 10f));
        label.setPreferredSize(new Dimension(92, 22));
        slider.setOpaque(false);
        slider.setPreferredSize(new Dimension(120, 22));
        if (help == null)
        {
            row.add(label, BorderLayout.WEST);
        }
        else
        {
            JPanel labelAndHelp = new JPanel(new BorderLayout(2, 0));
            labelAndHelp.setOpaque(false);
            label.setPreferredSize(new Dimension(72, 22));
            labelAndHelp.setPreferredSize(new Dimension(92, 22));
            labelAndHelp.add(label, BorderLayout.CENTER);
            labelAndHelp.add(help, BorderLayout.EAST);
            row.add(labelAndHelp, BorderLayout.WEST);
        }
        row.add(slider, BorderLayout.CENTER);
        return row;
    }
    private static JLabel centeredLabel()
    {
        return new JLabel("", SwingConstants.CENTER);
    }

    private static void styleProgress(JProgressBar bar, Color foreground)
    {
        bar.setForeground(foreground);
        bar.setBackground(new Color(47, 33, 35));
        bar.setBorder(BorderFactory.createLineBorder(new Color(128, 84, 50)));
        bar.setStringPainted(true);
        bar.setFont(bar.getFont().deriveFont(Font.BOLD, 9f));
    }

    private static String escape(String text)
    {
        return text.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;");
    }

    private static final class BookHeader extends JPanel
    {
        @Override
        protected void paintComponent(Graphics graphics)
        {
            Graphics copy = graphics.create();
            copy.setColor(INK);
            copy.fillRect(0, 0, getWidth(), getHeight());
            if (copy instanceof java.awt.Graphics2D)
            {
                java.awt.Graphics2D g = (java.awt.Graphics2D) copy;
                g.setPaint(new GradientPaint(0, 0, new Color(82, 49, 42),
                    getWidth(), getHeight(), new Color(39, 29, 35)));
                g.fillRect(0, 0, getWidth(), getHeight());
                g.setColor(new Color(255, 205, 100, 30));
                g.fillOval(-40, -60, getWidth() + 80, 150);
            }
            copy.dispose();
            super.paintComponent(graphics);
        }

        BookHeader()
        {
            setOpaque(false);
        }
    }
}

