    tags = {"pet", "pets", "animal", "cosmetic", "follower", "resize", "collection", "catch", "fun"}
)
public class PettingZooPlugin extends Plugin
{
    private static final int LOCAL_TILE_SIZE = 128;
    private static final int TELEPORT_DISTANCE = 15 * LOCAL_TILE_SIZE;
    private static final int THROW_ANIMATION = 5063;
    private static final int WINDUP_FRAMES = 16;
    private static final int FLIGHT_FRAMES = 30;
    private static final int IMPACT_FRAMES = 22;
