    private final Map<Integer, Integer> attackAnimations = new ConcurrentHashMap<>();
    private final Map<Integer, RecentCombatAnimation> recentCombatAnimations = new ConcurrentHashMap<>();
    private final Map<Long, BufferedImage> previewCache = new ConcurrentHashMap<>();
    private final RenderCallback renderCallback = new RenderCallback()
    {
