        public boolean addEntity(Renderable renderable, boolean drawingUi)
        {
            return shouldDraw(renderable);
        }
    };

    private NavigationButton navigationButton;
    private PettingZooPanel panel;
    private UnlockCatalogueWindow catalogueWindow;
    private final Map<String, CatalogueEntry> catalogueByAppearance = new LinkedHashMap<>();
    private volatile int catalogueScanIndex = -1;
    private volatile List<CatalogueEntry> catalogueSnapshot = new ArrayList<>();

    private RuneLiteObject petObject;
    private RuneLiteObject captureBall;
    private CaptureAttempt capture;
    private NPC temporarilyHiddenNpc;
    private int hiddenNpcTicks;
    private int activeNpcId = -1;
    private int activeScale = -1;
    private int idleAnimation = -1;
    private int walkAnimation = -1;
    private int playingAnimation = Integer.MIN_VALUE;
    private boolean petWasMoving;
    private boolean petInteractionPlaying;

    @Provides
    PettingZooConfig provideConfig(ConfigManager manager)
    {
        return manager.getConfig(PettingZooConfig.class);
    }

    @Override
    protected void startUp()
    {
        synchronized (collection)
        {
            collection.clear();
            collection.putAll(PetCollectionStore.parse(config.collection()));
        }
        lastXp.clear();
        attackAnimations.clear();
        attackAnimations.putAll(AttackAnimationStore.parse(config.attackAnimations()));
        recentCombatAnimations.clear();
        previewCache.clear();
        panel = new PettingZooPanel(this);
        navigationButton = NavigationButton.builder()
            .tooltip("Station's Creature Collector")
            .icon(ImageUtil.loadImageResource(PettingZooPlugin.class, "nav-icon.png"))
            .priority(7)
            .panel(panel)
            .build();
        clientToolbar.addNavigation(navigationButton);
        renderCallbackManager.register(renderCallback);
        clearPet();
        clearCapture(false);
        clearStaleThrowPose();
        modelFactory.clear();
        captureBallFactory.clear();
        refreshPanel();
        clientThread.invokeLater(this::sanitizeCollection);
    }

    @Override
    protected void shutDown()
    {

        renderCallbackManager.unregister(renderCallback);
        if (navigationButton != null)
        {
            clientToolbar.removeNavigation(navigationButton);
        }
        clearCapture(true);
        clearPet();
        modelFactory.clear();
        captureBallFactory.clear();
        previewCache.clear();
        recentCombatAnimations.clear();
        navigationButton = null;
        panel = null;
        UnlockCatalogueWindow oldCatalogue = catalogueWindow;
        catalogueWindow = null;
        catalogueScanIndex = -1;
        catalogueByAppearance.clear();
        if (oldCatalogue != null)
        {
            SwingUtilities.invokeLater(oldCatalogue::dispose);
        }
    }

    @Subscribe
    public void onMenuEntryAdded(MenuEntryAdded event)
    {
        MenuEntry original = event.getMenuEntry();
        NPC npc = original.getNpc();
        if (npc == null || !"Examine".equalsIgnoreCase(event.getOption())
            || !CreatureEligibility.isCatchable(npc)
            || (config.requireShift() && !client.isKeyPressed(KeyCode.KC_SHIFT)))
        {
            return;
        }

        PetRecord pet = discover(npc);
        if (pet.caught)
        {
            return;
        }
        client.getMenu().createMenuEntry(-1)
            .setOption("Catch [" + catchChance(pet.combatLevel) + "%]")
            .setTarget(original.getTarget())
            .setType(MenuAction.RUNELITE)
            .onClick(entry ->
            {
                PetRecord current = getRecord(pet.npcId);
                if (current == null || !current.caught)
                {
                    startCapture(npc, pet);
                }
            });
    }

    @Subscribe
    public void onClientTick(ClientTick event)
    {
        if (client.getGameState() != GameState.LOGGED_IN)
        {
            return;
        }
        if (hiddenNpcTicks > 0 && --hiddenNpcTicks == 0)
        {
            temporarilyHiddenNpc = null;
        }
        if (capture != null)
        {
            advanceCapture();
        }
        scanCatalogueBatch();

        Player player = client.getLocalPlayer();
        WorldView worldView = client.getTopLevelWorldView();
        if (player == null || worldView == null || player.getLocalLocation() == null)
        {
            return;
        }

        PetSpec spec = resolveSpec();
        if (spec == null)
        {
            clearPet();
            return;
        }
        ensurePet(spec, player.getLocalLocation(), worldView);
        if (petObject != null)
        {
            if (petInteractionPlaying)
            {
                if (!petObject.finished())
                {
                    return;
                }
                petInteractionPlaying = false;
                setPetAnimation(idleAnimation, true);
            }
            movePet(player.getLocalLocation(), worldView);
        }
    }

    @Subscribe
    public void onAnimationChanged(AnimationChanged event)
    {
        if (!(event.getActor() instanceof NPC))
        {
            return;
        }
        NPC npc = (NPC) event.getActor();
        int animation = npc.getAnimation();
        if (animation < 0 || npc.getInteracting() == null || animation == npc.getIdlePoseAnimation()
            || animation == npc.getWalkAnimation() || animation == npc.getRunAnimation()
            || animation == npc.getPoseAnimation())
        {
            return;
        }
        recentCombatAnimations.put(npc.getIndex(),
            new RecentCombatAnimation(npc, animation, client.getTickCount()));
    }

    @Subscribe
    public void onHitsplatApplied(HitsplatApplied event)
    {
        Player player = client.getLocalPlayer();
        if (player == null || event.getActor() != player || event.getHitsplat() == null
            || event.getHitsplat().getAmount() <= 0)
        {
            return;
        }
        int tick = client.getTickCount();
        RecentCombatAnimation match = null;
        for (RecentCombatAnimation candidate : recentCombatAnimations.values())
        {
            if (tick - candidate.tick > 12 || candidate.npc.getInteracting() != player)
            {
                continue;
            }
            if (match != null && match.npc != candidate.npc)
            {
                return;
            }
            match = candidate;
        }
        if (match != null && !Integer.valueOf(match.animation).equals(attackAnimations.get(match.npc.getId())))
        {
            attackAnimations.put(match.npc.getId(), match.animation);
            configManager.setConfiguration(PettingZooConfig.GROUP, "attackAnimations",
                AttackAnimationStore.serialize(attackAnimations));
            refreshPanel();
        }
    }
    @Subscribe
    public void onStatChanged(StatChanged event)
    {
        Integer previous = lastXp.put(event.getSkill(), event.getXp());
        if (previous == null)
        {
            return;
        }
        int gained = event.getXp() - previous;
        if (gained <= 0)
        {
            return;
        }

        int progress = Math.max(0, config.xpTowardBall()) + gained;
        int earned = progress / XP_PER_BALL;
        configManager.setConfiguration(PettingZooConfig.GROUP, "xpTowardBall", progress % XP_PER_BALL);
        if (earned > 0)
        {
            awardBalls(earned, earned == 1 ? "10,000 XP earned" : "XP milestone streak");
        }
        refreshPanel();
    }

    @Subscribe
    public void onNpcLootReceived(NpcLootReceived event)
    {
        if (BossDetector.isBoss(event.getNpc()))
        {
            awardBalls(1, event.getNpc().getName() + " defeated");
        }
    }

    @Subscribe
    public void onConfigChanged(ConfigChanged event)
    {
        if (!PettingZooConfig.GROUP.equals(event.getGroup()))
        {
            return;
        }
        if ("collection".equals(event.getKey()) || "captureBalls".equals(event.getKey())
            || "xpTowardBall".equals(event.getKey()))
        {
            refreshPanel();
            return;
        }
        if ("followDistance".equals(event.getKey()) || "chaseSpeed".equals(event.getKey()))
        {
            refreshPanel();
            return;
        }
        if ("attackAnimations".equals(event.getKey()))
        {
            return;
        }
        if ("forgetAdopted".equals(event.getKey()) && config.forgetAdopted())
        {
            configManager.setConfiguration(PettingZooConfig.GROUP, "adoptedNpcId", -1);
            configManager.setConfiguration(PettingZooConfig.GROUP, "adoptedName", "");
            configManager.setConfiguration(PettingZooConfig.GROUP, "adoptedIdle", -1);
            configManager.setConfiguration(PettingZooConfig.GROUP, "adoptedWalk", -1);
            configManager.setConfiguration(PettingZooConfig.GROUP, "forgetAdopted", false);
            configManager.setConfiguration(PettingZooConfig.GROUP, "petSource", PetSource.CURRENT_PET);
        }
        clearPet();
        modelFactory.clear();
        refreshPanel();
    }

    @Subscribe
    public void onGameStateChanged(GameStateChanged event)
    {
        if (event.getGameState() != GameState.LOGGED_IN)
        {
            clearCapture(true);
            clearPet();
        }
        else
        {
            clientThread.invokeLater(this::sanitizeCollection);
        }
    }

