    int catchChance(int combatLevel)
    {
        return catchChanceForLevel(config.catchChance(), combatLevel);
    }

    static int catchChanceForLevel(int baseChance, int combatLevel)
    {
        int base = Math.max(1, Math.min(100, baseChance));
        return combatLevel <= 0 ? base
            : Math.max(1, (int) Math.round(base / (1.0 + combatLevel / 60.0)));
    }

    void requestPreview(PetRecord pet, Consumer<BufferedImage> callback)
    {
        long key = ((long) pet.npcId << 1) | (pet.caught ? 1L : 0L);
        BufferedImage cached = previewCache.get(key);
        if (cached != null)
        {
            callback.accept(cached);
            return;
        }
        clientThread.invokeLater(() ->
        {
            Model model = modelFactory.get(pet.npcId, 100);
            BufferedImage image = model == null ? null
                : ModelPreviewRenderer.render(model, 92, 92, !pet.caught);
            if (image != null)
            {
                previewCache.put(key, image);
            }
            SwingUtilities.invokeLater(() -> callback.accept(image));
        });
    }

    private void awardBalls(int amount, String reason)
    {
        if (amount <= 0)
