        int updated = Math.max(0, config.captureBalls()) + amount;
        configManager.setConfiguration(PettingZooConfig.GROUP, "captureBalls", updated);
        message("Capture ball +" + amount + "! " + reason + ". You now have " + updated + ".");
        PettingZooPanel current = panel;
        if (current != null)
        {
            SwingUtilities.invokeLater(() -> current.showReward("+" + amount + " CAPTURE BALL"));
        }
        refreshPanel();
    }

