    void openUnlockCatalogue()
    {
        if (catalogueWindow == null)
        {
            catalogueWindow = new UnlockCatalogueWindow(this);
        }
        catalogueWindow.setVisible(true);
        catalogueWindow.toFront();
        if (catalogueScanIndex < 0 && catalogueByAppearance.isEmpty())
        {
            catalogueScanIndex = 0;
        }
        else if (catalogueScanIndex < 0)
        {
            publishCatalogue();
        }
    }

    boolean isCaught(int npcId)
    {
        PetRecord record = getRecord(npcId);
        return record != null && record.caught;
