    private void scanCatalogueBatch()
    {
        if (catalogueScanIndex < 0 || client.getGameState() != GameState.LOGGED_IN)
        {
            return;
        }
        int end = Math.min(CATALOGUE_MAX_NPC_ID, catalogueScanIndex + CATALOGUE_BATCH_SIZE);
        for (int id = catalogueScanIndex; id < end; id++)
        {
            NPCComposition composition = client.getNpcDefinition(id);
            if (composition == null)
            {
                continue;
            }
            if (composition.getConfigs() != null)
            {
                NPCComposition transformed = composition.transform();
                if (transformed != null)
                {
                    composition = transformed;
                }
            }
            String name = CreatureEligibility.cleanName(composition.getName());
            int[] models = composition.getModels();
            boolean alreadyDiscovered = getRecord(id) != null;
            if (name.isEmpty() || "null".equalsIgnoreCase(name)
                || models == null || models.length == 0 || !composition.isInteractible()
                || !alreadyDiscovered && !CreatureEligibility.isCatalogueCreature(name, composition))
            {
                continue;
            }
            Model catalogueModel = modelFactory.get(id, 100);
            if (ModelPreviewRenderer.render(catalogueModel, 32, 32, true) == null)
            {
                continue;
            }
            PetRecord pet = new PetRecord(id, name, -1, -1, composition.getCombatLevel(), false);
            String key = appearanceKey(pet, composition);
            int definitionId = composition.getId() >= 0 ? composition.getId() : id;
            NpcDefinitionData definition;
            try
            {
                definition = NpcDefinitionDecoder.decode(client.getIndexConfig().loadData(9, definitionId));
            }
            catch (RuntimeException ignored)
            {
                definition = new NpcDefinitionData();
            }
            CatalogueEntry candidate = new CatalogueEntry(id, name, composition.getCombatLevel(),
                ZooRegion.infer(name), definition.standingAnimation, definition.walkingAnimation);
            CatalogueEntry existing = catalogueByAppearance.get(key);
            if (existing == null || isCaught(candidate.npcId) && !isCaught(existing.npcId)
                || candidate.npcId < existing.npcId && isCaught(candidate.npcId) == isCaught(existing.npcId))
            {
                catalogueByAppearance.put(key, candidate);
            }
        }
        catalogueScanIndex = end;
        UnlockCatalogueWindow current = catalogueWindow;
        if (catalogueScanIndex >= CATALOGUE_MAX_NPC_ID)
        {
            catalogueScanIndex = -1;
            modelFactory.clear();
            publishCatalogue();
        }
        else if (current != null && catalogueScanIndex % 900 == 0)
        {
            int progress = catalogueScanIndex;
            SwingUtilities.invokeLater(() -> current.showScanProgress(progress, CATALOGUE_MAX_NPC_ID));
        }
    }

    void removeUnrenderableCatalogueEntry(int npcId)
    {
        clientThread.invokeLater(() ->
        {
            catalogueByAppearance.entrySet().removeIf(entry -> entry.getValue().npcId == npcId);
            List<CatalogueEntry> cleaned = new ArrayList<>(catalogueSnapshot);
            cleaned.removeIf(entry -> entry.npcId == npcId);
            catalogueSnapshot = cleaned;
            UnlockCatalogueWindow current = catalogueWindow;
            if (current != null)
            {
                SwingUtilities.invokeLater(() -> current.removeEntry(npcId));
            }
        });
    }
    private void publishCatalogue()
    {
        List<CatalogueEntry> entries = new ArrayList<>(catalogueByAppearance.values());
        entries.sort(Comparator.comparing((CatalogueEntry entry) -> entry.region.displayName)
            .thenComparing(entry -> entry.name).thenComparingInt(entry -> entry.npcId));
        catalogueSnapshot = entries;
        UnlockCatalogueWindow current = catalogueWindow;
        if (current != null)
        {
            SwingUtilities.invokeLater(() -> current.setEntries(entries));
        }

    }
    private void sanitizeCollection()
    {
        if (client.getGameState() != GameState.LOGGED_IN)
        {
            return;
        }

        Map<String, PetRecord> unique = new LinkedHashMap<>();
        int activeId = config.adoptedNpcId();
        synchronized (collection)
        {
            for (PetRecord pet : collection.values())
            {
                NPCComposition composition = client.getNpcDefinition(pet.npcId);
                if (composition != null && composition.getConfigs() != null)
                {
                    NPCComposition transformed = composition.transform();
                    if (transformed != null)
                    {
                        composition = transformed;
                    }
                }
                if (!CreatureEligibility.isCatchable(
                    pet.name, pet.idleAnimation, pet.walkAnimation, composition)
                    || !pet.caught && !CreatureEligibility.isCatalogueCreature(pet.name, composition))
                {
                    continue;
                }

                String key = appearanceKey(pet, composition);
                PetRecord existing = unique.get(key);
                if (existing == null || prefer(pet, existing, activeId))
                {
                    unique.put(key, pet);
                }
            }

            Map<Integer, PetRecord> cleaned = new TreeMap<>();
            for (PetRecord pet : unique.values())
            {
                cleaned.put(pet.npcId, pet);
            }
            if (cleaned.keySet().equals(collection.keySet()))
            {
                return;
            }
            collection.clear();
            collection.putAll(cleaned);
        }

        if (activeId >= 0 && getRecord(activeId) == null)
        {
            configManager.setConfiguration(PettingZooConfig.GROUP, "adoptedNpcId", -1);
            configManager.setConfiguration(PettingZooConfig.GROUP, "adoptedName", "");
            configManager.setConfiguration(PettingZooConfig.GROUP, "adoptedIdle", -1);
            configManager.setConfiguration(PettingZooConfig.GROUP, "adoptedWalk", -1);
            configManager.setConfiguration(PettingZooConfig.GROUP, "petSource", PetSource.CURRENT_PET);
            clearPet();
        }
        previewCache.clear();
        persistCollection();
        refreshPanel();
    }

    private static boolean prefer(PetRecord candidate, PetRecord existing, int activeId)
    {
        if (candidate.npcId == activeId)
        {
            return true;
        }
        if (existing.npcId == activeId)
        {
            return false;
        }
        if (candidate.caught != existing.caught)
        {
            return candidate.caught;
        }
        return candidate.npcId < existing.npcId;
    }

    private static String appearanceKey(PetRecord pet, NPCComposition composition)
    {
        if (composition == null)
        {
            return "id:" + pet.npcId;
        }
        return pet.name.toLowerCase(Locale.ENGLISH)
            + '|' + Arrays.hashCode(composition.getModels())
            + '|' + Arrays.hashCode(composition.getColorToReplace())
            + '|' + Arrays.hashCode(composition.getColorToReplaceWith())
            + '|' + composition.getWidthScale()
            + '|' + composition.getHeightScale();
    }

    private PetRecord discover(NPC npc)
    {
        PetRecord created = new PetRecord(npc.getId(), npc.getName(),
            npc.getIdlePoseAnimation(), npc.getWalkAnimation(), npc.getCombatLevel(), false);
        synchronized (collection)
        {
            PetRecord existing = collection.get(created.npcId);
            if (existing != null)
            {
                if (existing.combatLevel < 0 && created.combatLevel >= 0)
                {
                    existing = new PetRecord(existing.npcId, existing.name, existing.idleAnimation,
                        existing.walkAnimation, created.combatLevel, existing.caught);
                    collection.put(existing.npcId, existing);
                    persistCollection();
                }
                return existing;
            }
            collection.put(created.npcId, created);
        }
        persistCollection();
        refreshPanel();
        return created;
    }

    private PetRecord getRecord(int npcId)
    {
        synchronized (collection)
        {
            return collection.get(npcId);
        }
    }

    private void startCapture(NPC npc, PetRecord pet)
    {
        if (capture != null)
        {
            message("A capture ball is already in the air!");
            return;
        }
        if (config.captureBalls() <= 0)
        {
            message("You are out of capture balls. Earn one every 10,000 XP or from a boss kill.");
            return;
        }

        Player player = client.getLocalPlayer();
        LocalPoint start = player == null ? null : player.getLocalLocation();
        LocalPoint target = npc.getLocalLocation();
        WorldView worldView = client.getTopLevelWorldView();
        if (player == null || start == null || target == null || worldView == null
            || start.getWorldView() != target.getWorldView())
        {
            message("That creature is too far away to catch.");
            return;
        }
        if (captureBallFactory.create(0) == null)
        {
            message("The capture ball could not be loaded.");
            return;
        }

        configManager.setConfiguration(PettingZooConfig.GROUP, "captureBalls",
            Math.max(0, config.captureBalls() - 1));
        int oldAnimation = player.getAnimation();
        int oldAnimationFrame = player.getAnimationFrame();
        player.setAnimation(THROW_ANIMATION);
        player.setAnimationFrame(0);
        capture = new CaptureAttempt(pet, npc, start, target, worldView.getPlane(),
            oldAnimation, oldAnimationFrame);
        refreshPanel();
    }

    private void advanceCapture()
    {
        Player player = client.getLocalPlayer();
        WorldView worldView = client.getTopLevelWorldView();
        if (player == null || worldView == null)
        {
            clearCapture(true);
            return;
        }

        capture.frame++;
        LocalPoint liveTarget = capture.targetNpc.getLocalLocation();
        if (liveTarget != null && liveTarget.getWorldView() == capture.start.getWorldView())
        {
            capture.end = liveTarget;
        }
        if (capture.frame < WINDUP_FRAMES)
        {
            return;
        }

        if (capture.frame == WINDUP_FRAMES)
        {
            releaseThrowPose(capture);
            RuneLiteObject ball = client.createRuneLiteObject();
            ball.setModel(captureBallFactory.create(0));
            ball.setLocation(capture.start, capture.plane);
            ball.setRadius(60);
            ball.setActive(true);
            captureBall = ball;
        }
        if (captureBall == null)
        {
            clearCapture(true);
            return;
        }

        int flightFrame = capture.frame - WINDUP_FRAMES;
        if (flightFrame <= FLIGHT_FRAMES)
        {
            double progress = Math.min(1.0, flightFrame / (double) FLIGHT_FRAMES);
            int x = (int) Math.round(capture.start.getX()
                + (capture.end.getX() - capture.start.getX()) * progress);
            int y = (int) Math.round(capture.start.getY()
                + (capture.end.getY() - capture.start.getY()) * progress);
            int height = (int) Math.round(Math.sin(Math.PI * progress) * 245.0);
            Model frameModel = captureBallFactory.create(height);
            if (frameModel != null)
            {
                captureBall.setModel(frameModel);
            }
            captureBall.setLocation(new LocalPoint(x, y, capture.start.getWorldView()), capture.plane);
            captureBall.setOrientation(flightFrame * 116 & 2047);
        }

        if (flightFrame == FLIGHT_FRAMES)
        {
            capture.impacted = true;
            capture.success = random.nextInt(100) < catchChance(capture.pet.combatLevel);
        }
        if (capture.impacted)
        {
            int impactFrame = flightFrame - FLIGHT_FRAMES;
            int bounce = (int) Math.round(Math.abs(Math.sin(impactFrame * Math.PI / 8.0))
                * Math.max(0, 44 - impactFrame * 2));
            Model wobbleModel = captureBallFactory.create(bounce);
            if (wobbleModel != null)
            {
                captureBall.setModel(wobbleModel);
            }
            captureBall.setOrientation(impactFrame * 104 & 2047);
        }
        if (capture.frame >= WINDUP_FRAMES + FLIGHT_FRAMES + IMPACT_FRAMES)
        {
            finishCapture();
        }
    }

    private void finishCapture()
    {
        PetRecord attempted = capture.pet;
        NPC targetNpc = capture.targetNpc;
        boolean success = capture.success;
        clearCapture(true);
        if (success)
        {
            temporarilyHiddenNpc = targetNpc;
            hiddenNpcTicks = 24;
            PetRecord caught = attempted.caught();
            synchronized (collection)
            {
                collection.put(caught.npcId, caught);
            }
            persistCollection();
            activate(caught);
            message("Caught " + caught.name + "! It has been added to your Creature Collector.");
            PettingZooPanel current = panel;
            if (current != null)
            {
                SwingUtilities.invokeLater(() -> current.showNewPet(caught.name));
            }
        }
        else
        {
            message(attempted.name + " broke free in a puff of stars. Try again!");
            refreshPanel();
        }
    }

    private void activate(PetRecord pet)
    {
        if (!pet.caught)
        {
            return;
        }
        configManager.setConfiguration(PettingZooConfig.GROUP, "adoptedNpcId", pet.npcId);
        configManager.setConfiguration(PettingZooConfig.GROUP, "adoptedName", pet.name);
        configManager.setConfiguration(PettingZooConfig.GROUP, "adoptedIdle", pet.idleAnimation);
        configManager.setConfiguration(PettingZooConfig.GROUP, "adoptedWalk", pet.walkAnimation);
        configManager.setConfiguration(PettingZooConfig.GROUP, "petSource", PetSource.ADOPTED_ANIMAL);
        clearPet();
        modelFactory.clear();
        refreshPanel();
    }

    private void persistCollection()
    {
        String serialized;
        synchronized (collection)
        {
            serialized = PetCollectionStore.serialize(collection);
        }
        configManager.setConfiguration(PettingZooConfig.GROUP, "collection", serialized);
    }

    private void refreshPanel()
    {
        PettingZooPanel current = panel;
        if (current != null)
        {
            SwingUtilities.invokeLater(current::refresh);
        }
        UnlockCatalogueWindow catalogue = catalogueWindow;
        if (catalogue != null)
        {
            SwingUtilities.invokeLater(catalogue::refreshCaughtState);
        }
    }

    private PetSpec resolveSpec()
    {
        if (config.petSource() == PetSource.CURRENT_PET)
        {
            if (!config.customizeCurrentPet())
            {
                return null;
            }
            NPC follower = client.getFollower();
            return follower == null ? null
                : new PetSpec(follower.getId(), follower.getIdlePoseAnimation(), follower.getWalkAnimation());
        }
        return config.adoptedNpcId() < 0 ? null
            : new PetSpec(config.adoptedNpcId(), config.adoptedIdle(), config.adoptedWalk());
    }

    private void ensurePet(PetSpec spec, LocalPoint playerLocation, WorldView worldView)
    {
        int scale = config.petScale();
        if (petObject != null && petObject.isActive()
            && activeNpcId == spec.npcId && activeScale == scale)
        {
            return;
        }
        clearPet();
        Model model = modelFactory.get(spec.npcId, scale);
        if (model == null)
        {
            return;
        }

        RuneLiteObject created = client.createRuneLiteObject();
        created.setModel(model);
        int gap = config.followDistance() * LOCAL_TILE_SIZE;
        created.setLocation(playerLocation.plus(-gap / 2, -gap / 2), worldView.getPlane());
        created.setOrientation(1024);
        created.setRadius(Math.max(60, 60 * scale / 100));
        created.setActive(true);
        petObject = created;
        activeNpcId = spec.npcId;
        activeScale = scale;
        idleAnimation = spec.idleAnimation;
        walkAnimation = spec.walkAnimation;
        setPetAnimation(idleAnimation);
    }

    private void movePet(LocalPoint target, WorldView worldView)
    {
        LocalPoint current = petObject.getLocation();
        if (current == null || current.getWorldView() != target.getWorldView()
            || current.distanceTo(target) > TELEPORT_DISTANCE)
        {
            int gap = config.followDistance() * LOCAL_TILE_SIZE;
            petObject.setLocation(target.plus(-gap / 2, -gap / 2), worldView.getPlane());
            setPetAnimation(idleAnimation, petWasMoving);
            petWasMoving = false;
            return;
        }

        PetMovement.Step step = PetMovement.advance(
            current.getX(), current.getY(), target.getX(), target.getY(),
            config.followDistance() * LOCAL_TILE_SIZE, config.chaseSpeed(), petObject.getOrientation());
        petObject.setLocation(new LocalPoint(step.x, step.y, target.getWorldView()), worldView.getPlane());
        petObject.setOrientation(step.orientation);
        if (step.moving)
        {
            setPetAnimation(usableWalkAnimation());
        }
        else
        {
            setPetAnimation(idleAnimation, petWasMoving);
        }
        petWasMoving = step.moving;
    }

    private int usableWalkAnimation()
    {
        return walkAnimation >= 0 ? walkAnimation : idleAnimation;
    }

    private void setPetAnimation(int animationId)
    {
        setPetAnimation(animationId, false);
    }

    private void setPetAnimation(int animationId, boolean forceRestart)
    {
        if (petObject == null || !forceRestart && animationId == playingAnimation)
        {
            return;
        }
        if (forceRestart)
        {
            petObject.setAnimation(null);
            playingAnimation = Integer.MIN_VALUE;
        }
        Animation animation = animationId < 0 ? null : client.loadAnimation(animationId);
        petObject.setAnimation(animation);
        petObject.setShouldLoop(animation != null);
        playingAnimation = animationId;
    }

    private boolean shouldDraw(Renderable renderable)
    {
        if (capture != null && capture.impacted && renderable == capture.targetNpc
            || hiddenNpcTicks > 0 && renderable == temporarilyHiddenNpc)
        {
            return false;
        }
        return !(config.hideRealPet() && petObject != null && petObject.isActive()
            && renderable == client.getFollower());
    }

    private void clearCapture(boolean restoreAnimation)
    {
        CaptureAttempt old = capture;
        capture = null;
        if (captureBall != null)
        {
            captureBall.setActive(false);
            if (client.isRuneLiteObjectRegistered(captureBall))
            {
                client.removeRuneLiteObject(captureBall);
            }
            captureBall = null;
        }
        if (restoreAnimation && old != null)
        {
            releaseThrowPose(old);
        }
    }

    private void releaseThrowPose(CaptureAttempt attempt)
    {
        if (attempt == null || attempt.throwPoseReleased)
        {
            return;
        }

        Player player = client.getLocalPlayer();
        if (player != null && player.getAnimation() == THROW_ANIMATION)
        {
            int animation = attempt.oldAnimation == THROW_ANIMATION ? -1 : attempt.oldAnimation;
            player.setAnimation(animation);
            player.setAnimationFrame(animation < 0 ? 0 : attempt.oldAnimationFrame);
        }
        attempt.throwPoseReleased = true;
    }

    private void clearStaleThrowPose()
    {
        Player player = client.getLocalPlayer();
        if (player != null && player.getAnimation() == THROW_ANIMATION)
        {
            player.setAnimation(-1);
            player.setAnimationFrame(0);
        }
    }

    private void clearPet()
    {
        if (petObject != null)
        {
            petObject.setActive(false);
            if (client.isRuneLiteObjectRegistered(petObject))
            {
                client.removeRuneLiteObject(petObject);
            }
        }
        petObject = null;
        activeNpcId = -1;
        activeScale = -1;
        idleAnimation = -1;
        walkAnimation = -1;
        playingAnimation = Integer.MIN_VALUE;
        petWasMoving = false;
        petInteractionPlaying = false;
    }

    private void message(String text)
    {
        client.addChatMessage(ChatMessageType.GAMEMESSAGE, "",
            "[Station's Creature Collector] " + text, null);
    }

    private static final class RecentCombatAnimation
    {
        final NPC npc;
        final int animation;
        final int tick;

        RecentCombatAnimation(NPC npc, int animation, int tick)
        {
            this.npc = npc;
            this.animation = animation;
            this.tick = tick;
        }
    }
    private static final class PetSpec
    {
        final int npcId;
        final int idleAnimation;
        final int walkAnimation;

        PetSpec(int npcId, int idleAnimation, int walkAnimation)
        {
            this.npcId = npcId;
            this.idleAnimation = idleAnimation;
            this.walkAnimation = walkAnimation;
        }
    }

    private static final class CaptureAttempt
    {
        final PetRecord pet;
        final NPC targetNpc;
        final LocalPoint start;
        LocalPoint end;
        final int plane;
        final int oldAnimation;
        final int oldAnimationFrame;
        int frame;
        boolean impacted;
        boolean success;
        boolean throwPoseReleased;

        CaptureAttempt(PetRecord pet, NPC targetNpc, LocalPoint start, LocalPoint end,
            int plane, int oldAnimation, int oldAnimationFrame)
        {
            this.pet = pet;
            this.targetNpc = targetNpc;
            this.start = start;
            this.end = end;
            this.plane = plane;
            this.oldAnimation = oldAnimation;
            this.oldAnimationFrame = oldAnimationFrame;
        }
    }
}

