final class UnlockCatalogueWindow extends JFrame
{
    private static final int PAGE_SIZE = 30;
    private static final Color GOLD = new Color(244, 194, 85);
    private static final Color PARCHMENT = new Color(238, 214, 171);
    private final PettingZooPlugin plugin;
    private final JLabel status = center();
    private final JProgressBar overall = new JProgressBar();
    private final JComboBox<ZooRegion> region = new JComboBox<>(ZooRegion.values());
    private final JTextField search = new JTextField();
    private final JPanel cards = new JPanel(new GridLayout(0, 5, 8, 8));
    private final JButton previous = new JButton("← PREVIOUS");
    private final JButton next = new JButton("NEXT →");
    private final JLabel pageLabel = center();
    private List<CatalogueEntry> entries = Collections.emptyList();
    private int generation;
    private int page;

    UnlockCatalogueWindow(PettingZooPlugin plugin)
    {
        super("Station's Creature Collector — Potential Unlocks");
        this.plugin = plugin;
        setDefaultCloseOperation(WindowConstants.HIDE_ON_CLOSE);
        setMinimumSize(new Dimension(760, 560));
        setSize(980, 720);
        setLocationByPlatform(true);

        JPanel root = new JPanel(new BorderLayout(10, 10));
        root.setBackground(new Color(34, 27, 30));
        root.setBorder(BorderFactory.createEmptyBorder(12, 12, 12, 12));
        setContentPane(root);

        JPanel header = new JPanel(new GridLayout(0, 1, 0, 6));
        header.setBackground(new Color(70, 43, 38));
        header.setBorder(BorderFactory.createCompoundBorder(
            BorderFactory.createLineBorder(new Color(139, 91, 48), 2),
            BorderFactory.createEmptyBorder(10, 12, 10, 12)));
        JLabel title = center();
        title.setText("THE GREAT GIELINOR CREATURE CATALOGUE");
        title.setFont(title.getFont().deriveFont(Font.BOLD, 20f));
        title.setForeground(new Color(255, 231, 174));
        status.setForeground(PARCHMENT);
        overall.setStringPainted(true);
        overall.setForeground(GOLD);
        overall.setBackground(new Color(42, 31, 32));
        overall.setBorder(BorderFactory.createLineBorder(new Color(128, 84, 50)));
        search.setToolTipText("Search every potential unlock");
        header.add(title);
        header.add(status);
        header.add(overall);

        JPanel filters = new JPanel(new GridLayout(1, 2, 8, 0));
        filters.setOpaque(false);
        filters.add(region);
        filters.add(search);
        header.add(filters);
        root.add(header, BorderLayout.NORTH);

        cards.setBackground(new Color(38, 30, 34));
        cards.setBorder(BorderFactory.createEmptyBorder(6, 6, 6, 6));
        JScrollPane scroll = new JScrollPane(cards);
        scroll.setHorizontalScrollBarPolicy(JScrollPane.HORIZONTAL_SCROLLBAR_NEVER);
        scroll.getVerticalScrollBar().setUnitIncrement(28);
        scroll.setBorder(BorderFactory.createLineBorder(new Color(105, 71, 50)));
        root.add(scroll, BorderLayout.CENTER);

        JPanel paging = new JPanel(new GridLayout(1, 3, 8, 0));
        paging.setOpaque(false);
        pageLabel.setForeground(PARCHMENT);
        previous.addActionListener(event -> { if (page > 0) { page--; rebuild(); } });
        next.addActionListener(event -> { page++; rebuild(); });
        paging.add(previous);
        paging.add(pageLabel);
        paging.add(next);
        root.add(paging, BorderLayout.SOUTH);

        region.addActionListener(event -> { page = 0; rebuild(); });
        search.getDocument().addDocumentListener(new DocumentListener()
        {
            @Override public void insertUpdate(DocumentEvent e) { page = 0; rebuild(); }
            @Override public void removeUpdate(DocumentEvent e) { page = 0; rebuild(); }
            @Override public void changedUpdate(DocumentEvent e) { page = 0; rebuild(); }
        });
        showScanProgress(0, 20_000);
    }

    void showScanProgress(int scanned, int maximum)
    {
        status.setText("Reading creature models… " + Math.min(100, scanned * 100 / maximum) + "%");
        overall.setMaximum(maximum);
        overall.setValue(scanned);
        overall.setString("BUILDING MASTER CATALOGUE");
    }

    void setEntries(List<CatalogueEntry> values)
    {
        entries = new ArrayList<>(values);
        entries.sort(Comparator.comparing((CatalogueEntry e) -> e.region.displayName)
            .thenComparing(e -> e.name).thenComparingInt(e -> e.npcId));
        rebuild();
    }

    void removeEntry(int npcId)
    {
        if (entries.removeIf(entry -> entry.npcId == npcId))
        {
            rebuild();
        }
    }
    void refreshCaughtState()
    {
        if (!entries.isEmpty()) rebuild();
    }

    private void rebuild()
    {
        int currentGeneration = ++generation;
        ZooRegion selected = (ZooRegion) region.getSelectedItem();
        String query = search.getText().trim().toLowerCase();
        List<CatalogueEntry> visible = new ArrayList<>();
        int total = 0;
        int caught = 0;
        for (CatalogueEntry entry : entries)
        {
            if (selected == ZooRegion.ALL || entry.region == selected)
            {
                total++;
                if (plugin.isCaught(entry.npcId)) caught++;
                if (query.isEmpty() || entry.name.toLowerCase().contains(query)
                    || Integer.toString(entry.npcId).contains(query))
                {
                    visible.add(entry);
                }
            }
        }
        int percent = total == 0 ? 0 : Math.round(caught * 100f / total);
        String label = selected == null ? ZooRegion.ALL.displayName : selected.displayName;
        status.setText(label + "  •  " + caught + " / " + total + " adopted  •  " + percent + "% complete");
        overall.setMaximum(Math.max(1, total));
        overall.setValue(caught);
        overall.setString(percent + "%  " + label.toUpperCase());

        int pages = Math.max(1, (visible.size() + PAGE_SIZE - 1) / PAGE_SIZE);
        page = Math.min(page, pages - 1);
        previous.setEnabled(page > 0);
        next.setEnabled(page + 1 < pages);
        pageLabel.setText((page + 1) + " / " + pages + "  •  " + visible.size() + " unlocks");

        cards.removeAll();
        int from = page * PAGE_SIZE;
        int to = Math.min(visible.size(), from + PAGE_SIZE);
        for (int index = from; index < to; index++)
        {
            cards.add(card(visible.get(index), currentGeneration));
        }
        if (visible.isEmpty())
        {
            JLabel empty = center();
            empty.setForeground(PARCHMENT);
            empty.setText(entries.isEmpty() ? "Building the master catalogue…" : "No unlocks match this page");
            cards.add(empty);
        }
        cards.revalidate();
        cards.repaint();
    }

    private JPanel card(CatalogueEntry entry, int currentGeneration)
    {
        boolean caught = plugin.isCaught(entry.npcId);
        JPanel card = new JPanel(new BorderLayout(3, 4));
        card.setPreferredSize(new Dimension(150, 184));
        card.setBackground(caught ? new Color(75, 51, 42) : new Color(49, 40, 45));
        card.setBorder(BorderFactory.createCompoundBorder(
            BorderFactory.createLineBorder(caught ? GOLD : new Color(92, 75, 82), caught ? 2 : 1),
            BorderFactory.createEmptyBorder(5, 5, 5, 5)));
        JLabel portrait = center();
        portrait.setPreferredSize(new Dimension(120, 112));
        portrait.setText("…");
        card.add(portrait, BorderLayout.CENTER);
        JLabel text = center();
        text.setForeground(caught ? new Color(255, 224, 145) : new Color(219, 208, 212));
        text.setText("<html><center><b>" + escape(entry.name) + "</b><br><small>"
            + entry.region.displayName + "<br>" + (caught ? "ADOPTED" : "LOCKED") + "</small></center></html>");
        card.add(text, BorderLayout.SOUTH);
        PetRecord preview = new PetRecord(entry.npcId, entry.name, -1, -1, entry.combatLevel, caught);
        plugin.requestPreview(preview, image ->
        {
            if (image == null)
            {
                plugin.removeUnrenderableCatalogueEntry(entry.npcId);
                return;
            }
            if (generation == currentGeneration)
            {
                portrait.setText("");
                portrait.setIcon(new ImageIcon(image));
            }
        });
        return card;
    }

    private static JLabel center()
    {
        return new JLabel("", SwingConstants.CENTER);
    }

    private static String escape(String text)
    {
        return text.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;");
    }
}

package com.pettingzoo;

import java.util.Locale;

enum ZooRegion
{
    ALL("All Gielinor"),
    MISTHALIN("Misthalin"),
    ASGARNIA("Asgarnia"),
    KANDARIN("Kandarin"),
    KARAMJA("Karamja"),
    KOUREND("Great Kourend"),
    VARLAMORE("Varlamore"),
    MORYTANIA("Morytania"),
    TIRANNWN("Tirannwn"),
    FREMENNIK("Fremennik"),
    DESERT("Kharidian Desert"),
    WILDERNESS("Wilderness"),
    OCEAN("Oceans & Islands"),
    WORLDWIDE("Across Gielinor");

    final String displayName;

    ZooRegion(String displayName)
    {
        this.displayName = displayName;
    }

    static ZooRegion infer(String value)
    {
        String name = value == null ? "" : value.toLowerCase(Locale.ENGLISH);
        if (has(name, "revenant", "callisto", "venenatis", "vet'ion", "scorpia", "chaos elemental", "lava dragon")) return WILDERNESS;
        if (has(name, "kalphite", "scarab", "crocodile", "jackal", "desert lizard", "locust", "mummy", "akkha", "kephri", "zebak")) return DESERT;
        if (has(name, "vampyre", "vyre", "ghast", "snail", "bloodveld", "nightmare", "araxyte", "barrows", "banshee")) return MORYTANIA;
        if (has(name, "lizardman", "shayzien", "hosidius", "arceuus", "lovakengj", "piscarilius", "wintertodt", "hespori")) return KOUREND;
        if (has(name, "hueycoatl", "moons of peril", "jaguar", "antelope", "quetzal", "amoxliatl", "nagua")) return VARLAMORE;
        if (has(name, "dagannoth", "yak", "basilisk", "fremennik", "lunar", "vorkath", "rock lobster")) return FREMENNIK;
        if (has(name, "zulrah", "crystal", "seren", "prifddinas")) return TIRANNWN;
        if (has(name, "jungle", "karamja", "jogre", "broodoo", "monkey", "ape atoll", "tzhaar", "jad", "zuk")) return KARAMJA;
        if (has(name, "chompy", "terrorbird", "warped", "ourania", "piscatoris")) return KANDARIN;
        if (has(name, "mole", "cerberus", "burthorpe", "falador", "white wolf")) return ASGARNIA;
        if (has(name, "lumbridge", "varrock", "draynor", "surok", "champion")) return MISTHALIN;
        if (has(name, "albatross", "seagull", "shark", "whale", "dolphin", "marlin", "swordfish", "sea snake", "kraken", "leviathan")) return OCEAN;
        return WORLDWIDE;
    }

    private static boolean has(String value, String... needles)
    {
        for (String needle : needles)
        {
            if (value.contains(needle)) return true;
        }
        return false;
    }

    @Override
    public String toString()
    {
        return displayName;
    }
}

