package com.pettingzoo;

import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

public class CatchChanceTest
{
    @Test
    public void unlevelledCreaturesUseBaseChance()
    {
        assertEquals(35, PettingZooPlugin.catchChanceForLevel(35, -1));
        assertEquals(35, PettingZooPlugin.catchChanceForLevel(35, 0));
    }

    @Test
    public void chanceFallsAsCombatLevelRises()
    {
        int level10 = PettingZooPlugin.catchChanceForLevel(35, 10);
        int level100 = PettingZooPlugin.catchChanceForLevel(35, 100);
        int level500 = PettingZooPlugin.catchChanceForLevel(35, 500);

        assertTrue(level10 < 35);
        assertTrue(level100 < level10);
        assertTrue(level500 < level100);
    }

    @Test
    public void evenExtremeBossesRemainCatchable()
    {
        assertEquals(1, PettingZooPlugin.catchChanceForLevel(35, 10_000));
    }
}

package com.pettingzoo;

import java.lang.reflect.Proxy;
import net.runelite.api.NPCComposition;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class CreatureEligibilityTest
{
    @Test
    public void detectsStandardHumanRigs()
    {
        assertTrue(CreatureEligibility.isHumanAnimation(808, 819));
        assertTrue(CreatureEligibility.isHumanAnimation(813, 4226));
        assertFalse(CreatureEligibility.isHumanAnimation(5859, 5860));
    }

    @Test
    public void detectsHumanServiceInteractions()
    {
        assertTrue(CreatureEligibility.hasHumanServiceAction(
            new String[]{"Talk-to", "Trade", null, "Examine"}));
        assertTrue(CreatureEligibility.hasHumanServiceAction(
            new String[]{"Pickpocket", "Examine"}));
        assertFalse(CreatureEligibility.hasHumanServiceAction(
            new String[]{"Attack", "Pet", "Examine"}));
    }

    @Test
    public void stripsCacheColourTags()
    {
        assertEquals("Abyssal portal", CreatureEligibility.cleanName(
            "<col=00ffff>Abyssal portal</col>"));
    }

    @Test
    public void catalogueRejectsPropsEffectsAndHumans()
    {
        assertFalse(CreatureEligibility.isCatalogueCreature("Abyssal portal",
            composition(0, false, new String[]{"Enter"})));
        assertFalse(CreatureEligibility.isCatalogueCreature("Ammunition crate",
            composition(0, false, new String[]{"Search"})));
        assertFalse(CreatureEligibility.isCatalogueCreature("Augur Metzli",
            composition(0, false, new String[]{"Talk-to"})));
        assertFalse(CreatureEligibility.isCatalogueCreature("Blood wave",
            composition(0, false, null)));
    }

    @Test
    public void catalogueKeepsAnimalsPetsAndAttackableMonsters()
    {
        assertTrue(CreatureEligibility.isCatalogueCreature("Rat",
            composition(1, false, new String[]{"Attack"})));
        assertTrue(CreatureEligibility.isCatalogueCreature("Chiribaya",
            composition(0, true, new String[]{"Talk-to"})));
        assertTrue(CreatureEligibility.isCatalogueCreature("Unusual beast",
            composition(42, false, new String[]{"Attack"})));
    }

    @Test
    public void rejectsOfficialPetsAndTheirSourceBossesEverywhere()
    {
        NPCComposition attackable = composition(464, false, new String[]{"Attack", "Examine"});
        assertFalse(CreatureEligibility.isCatchable("Spindel", 1, 2, attackable));
        assertFalse(CreatureEligibility.isCatalogueCreature("Spindel", attackable));
        assertFalse(CreatureEligibility.isCatchable("Venenatis spiderling", 1, 2, attackable));
        assertFalse(CreatureEligibility.isCatalogueCreature("Venenatis spiderling", attackable));
    }
    @Test
    public void rejectsOnlyTheImmobileGemstoneCrabSpecialCase()
    {
        NPCComposition attackable = composition(160, false, new String[]{"Attack", "Examine"});
        assertTrue(CreatureEligibility.isExplicitlyExcluded("Gemstone Crab"));
        assertFalse(CreatureEligibility.isExplicitlyExcluded("Rock Crab"));
        assertFalse(CreatureEligibility.isCatchable("Gemstone Crab", 1, 2, attackable));
        assertFalse(CreatureEligibility.isCatalogueCreature("Gemstone Crab", attackable));
        assertTrue(CreatureEligibility.isCatchable("Rock Crab", 1, 2, attackable));
    }
    private static NPCComposition composition(int combat, boolean follower, String[] actions)
    {
        return (NPCComposition) Proxy.newProxyInstance(
            NPCComposition.class.getClassLoader(), new Class<?>[]{NPCComposition.class},
            (proxy, method, args) ->
            {
                switch (method.getName())
                {
                    case "getCombatLevel": return combat;
                    case "isFollower": return follower;
                    case "getActions": return actions;
                    case "getModels": return new int[]{1};
                    case "getName": return "test";
                    case "isInteractible": return true;
                    case "getSize":
                    case "getWidthScale":
                    case "getHeightScale":
                    case "getFootprintSize":
                    case "getId": return 1;
                    case "toString": return "NPCComposition(test)";
                    case "hashCode": return 1;
                    case "equals": return proxy == args[0];
                    default:
                        Class<?> type = method.getReturnType();
                        if (type == boolean.class) return false;
                        if (type == int.class) return 0;
                        return null;
                }
            });
    }
}

package com.pettingzoo;

import org.junit.Test;

import static org.junit.Assert.assertEquals;

public class NpcDefinitionDecoderTest
{
    @Test
    public void decodesIdleAndWalkAnimations()
    {
        NpcDefinitionData definition = NpcDefinitionDecoder.decode(new byte[]{
            13, 0x12, 0x34,
            14, 0x23, 0x45,
            0
        });
        assertEquals(0x1234, definition.standingAnimation);
        assertEquals(0x2345, definition.walkingAnimation);
    }

    @Test
    public void decodesDirectionalWalkOpcode()
    {
        NpcDefinitionData definition = NpcDefinitionDecoder.decode(new byte[]{
            17, 0x01, 0x02, 0, 1, 0, 2, 0, 3,
            0
        });
        assertEquals(0x0102, definition.walkingAnimation);
    }
}

