package com.pettingzoo;

import java.util.Map;
import java.util.TreeMap;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class PetCollectionStoreTest
{
    @Test
    public void roundTripsNamesAnimationsAndCatchState()
    {
        Map<Integer, PetRecord> pets = new TreeMap<>();
        pets.put(42, new PetRecord(42, "Stray dog", 100, 101, 126, true));
        pets.put(7, new PetRecord(7, "Gertrude's cat", -1, 55, false));

        Map<Integer, PetRecord> decoded = PetCollectionStore.parse(PetCollectionStore.serialize(pets));

        assertEquals(2, decoded.size());
        assertEquals("Stray dog", decoded.get(42).name);
        assertEquals(100, decoded.get(42).idleAnimation);
        assertEquals(126, decoded.get(42).combatLevel);
        assertTrue(decoded.get(42).caught);
        assertEquals("Gertrude's cat", decoded.get(7).name);
        assertFalse(decoded.get(7).caught);
    }

    @Test
    public void ignoresDamagedEntries()
    {
        Map<Integer, PetRecord> decoded = PetCollectionStore.parse("broken;4|x|2|1|bad");
        assertTrue(decoded.isEmpty());
    }
}

package com.pettingzoo;

import org.junit.Test;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class PetMovementTest
{
    @Test
    public void staysStillInsideFollowDistance()
    {
        PetMovement.Step step = PetMovement.advance(0, 0, 100, 0, 128, 20, 0);
        assertFalse(step.moving);
        assertTrue(step.x == 0 && step.y == 0);
    }

    @Test
    public void stopsWhenTheFinalSubCoordinateStepRoundsToTheSameSpot()
    {
        PetMovement.Step step = PetMovement.advance(0, 0, 91, 91, 128, 20, 0);
        assertFalse(step.moving);
        assertTrue(step.x == 0 && step.y == 0);
    }
    @Test
    public void turnsNpcModelTowardItsTravelDirection()
    {
        PetMovement.Step step = PetMovement.advance(0, 0, 500, 0, 128, 20, 0);
        assertTrue(step.moving);
        assertTrue(step.orientation > 1900);
    }

    @Test
    public void advancesTowardDistantPlayerWithoutOvershootingGap()
    {
        PetMovement.Step step = PetMovement.advance(0, 0, 500, 0, 128, 20, 0);
        assertTrue(step.moving);
        assertTrue(step.x > 0 && step.x <= 20);
        assertTrue(step.y == 0);
    }
}

