package com.pettingzoo;

import org.junit.Test;

import static org.junit.Assert.assertEquals;

public class ZooRegionTest
{
    @Test
    public void assignsDistinctiveCreaturesToTheirHomelands()
    {
        assertEquals(ZooRegion.DESERT, ZooRegion.infer("Kalphite Queen"));
        assertEquals(ZooRegion.MORYTANIA, ZooRegion.infer("Araxyte"));
        assertEquals(ZooRegion.WILDERNESS, ZooRegion.infer("Revenant dragon"));
        assertEquals(ZooRegion.KOUREND, ZooRegion.infer("Lizardman shaman"));
        assertEquals(ZooRegion.VARLAMORE, ZooRegion.infer("Hueycoatl"));
        assertEquals(ZooRegion.OCEAN, ZooRegion.infer("Albatross"));
    }

    @Test
    public void doesNotInventAHomeForGenericCreatures()
    {
        assertEquals(ZooRegion.WORLDWIDE, ZooRegion.infer("Rat"));
        assertEquals(ZooRegion.WORLDWIDE, ZooRegion.infer("Dog"));
    }
}
